create table if not exists public.business_categories (id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,name text not null,kind text not null check(kind in ('ENTRADA','SAIDA')),active boolean not null default true,created_at timestamptz not null default now(),unique(business_id,name,kind));
create table if not exists public.business_payment_methods (id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),unique(business_id,name));
create index if not exists idx_business_categories_business on public.business_categories(business_id); create index if not exists idx_business_payment_methods_business on public.business_payment_methods(business_id);
alter table public.business_categories enable row level security; alter table public.business_payment_methods enable row level security;
drop policy if exists business_categories_select on public.business_categories; drop policy if exists business_categories_insert on public.business_categories; drop policy if exists business_categories_update on public.business_categories; drop policy if exists business_categories_delete on public.business_categories; create policy business_categories_select on public.business_categories for select to authenticated using ((select public.current_household_id())=household_id); create policy business_categories_insert on public.business_categories for insert to authenticated with check ((select public.current_household_id())=household_id); create policy business_categories_update on public.business_categories for update to authenticated using ((select public.current_household_id())=household_id) with check ((select public.current_household_id())=household_id); create policy business_categories_delete on public.business_categories for delete to authenticated using ((select public.current_household_id())=household_id);
drop policy if exists business_payment_methods_select on public.business_payment_methods; drop policy if exists business_payment_methods_insert on public.business_payment_methods; drop policy if exists business_payment_methods_update on public.business_payment_methods; drop policy if exists business_payment_methods_delete on public.business_payment_methods; create policy business_payment_methods_select on public.business_payment_methods for select to authenticated using ((select public.current_household_id())=household_id); create policy business_payment_methods_insert on public.business_payment_methods for insert to authenticated with check ((select public.current_household_id())=household_id); create policy business_payment_methods_update on public.business_payment_methods for update to authenticated using ((select public.current_household_id())=household_id) with check ((select public.current_household_id())=household_id); create policy business_payment_methods_delete on public.business_payment_methods for delete to authenticated using ((select public.current_household_id())=household_id);
grant select,insert,update,delete on public.business_categories to authenticated; grant select,insert,update,delete on public.business_payment_methods to authenticated;